<template><div class="demo-widget chat-widget" :style="{...widgetStyle(s),background:hexAlpha(s.background,s.backgroundOpacity)}"><header><b>Twitch Chat</b><span>Simulated</span></header><div class="chat-lines" :class="s.direction"><p v-for="message in visible" :key="message.id"><strong v-if="s.showUsername">{{ message.badge }}{{ message.user }}</strong> {{ message.text }}</p></div></div></template>
<script setup>import { computed, ref, watch } from 'vue'; import { widgetStyle, useWidgetEvents } from './widgetHelpers.js'; const props=defineProps({widget:{type:Object,required:true}}); const s=props.widget.settings; const messages=ref([{id:1,user:'RavenAsh',badge:'★ ',text:'Ready for the next mission?'},{id:2,user:'PixelPilot',badge:'',text:'The squad is online!'}]); const event=useWidgetEvents(props.widget,{id:'initial',actor:{displayName:''},payload:{text:''}}); watch(event,(next)=>{const text=String(next.payload?.text||''); if((s.hideBotMessages&&next.payload?.isBot)||(s.hideCommands&&text.startsWith('!')))return; messages.value.push({id:next.id,user:next.actor?.displayName||'Viewer',badge:s.showBadges?'◆ ':'',text}); messages.value=messages.value.slice(-Number(s.maxMessages||6))},{deep:true}); const visible=computed(()=>s.direction==='down'?[...messages.value].reverse():messages.value); function hexAlpha(hex,alpha){if(!/^#[0-9a-f]{6}$/i.test(hex||''))return hex;return `${hex}${Math.round(Number(alpha)*255).toString(16).padStart(2,'0')}`}</script>
